package br.com.inframonitor.security;
import br.com.inframonitor.common.api.ErroResposta; import br.com.inframonitor.usuario.entity.Usuario; import br.com.inframonitor.usuario.repository.UsuarioRepository; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.http.MediaType; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.filter.OncePerRequestFilter; import tools.jackson.databind.ObjectMapper; import java.io.IOException; import java.util.List;
public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final UsuarioRepository users; private final ApiAuthenticationEntryPoint entry; private final ObjectMapper mapper; public JwtAuthenticationFilter(JwtService jwt,UsuarioRepository users,ApiAuthenticationEntryPoint entry,ObjectMapper mapper){this.jwt=jwt;this.users=users;this.entry=entry;this.mapper=mapper;}
 protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain chain)throws ServletException,IOException { String h=r.getHeader("Authorization"); if(h==null||h.isBlank()){chain.doFilter(r,s);return;} if(!h.startsWith("Bearer ")||h.length()<=7){entry.commence(r,s,null);return;} try { Long id=jwt.extrairUsuarioId(h.substring(7)); Usuario u=users.findById(id).orElseThrow(()->new JwtException("usuario ausente")); if(!u.isAtivo()) {entry.commence(r,s,null);return;} if(u.isTrocaSenhaObrigatoria() && !allowedDuringPasswordChange(r)){s.setStatus(403);s.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(s.getOutputStream(), ErroResposta.de(403,"Forbidden","PASSWORD_CHANGE_REQUIRED","Troca de senha obrigatoria",r.getRequestURI()));return;} UsuarioPrincipal p=new UsuarioPrincipal(u.getId(),u.getPapel()); var a=new UsernamePasswordAuthenticationToken(p,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getPapel().name()))); SecurityContextHolder.getContext().setAuthentication(a); chain.doFilter(r,s); } catch(JwtException|IllegalArgumentException e){SecurityContextHolder.clearContext();entry.commence(r,s,null);} }
 private boolean allowedDuringPasswordChange(HttpServletRequest request){return (request.getMethod().equals("GET")&&request.getRequestURI().equals("/api/v1/auth/me"))||(request.getMethod().equals("PUT")&&request.getRequestURI().equals("/api/v1/usuarios/me/senha"));}
}
